const items = $input.all();
const results = [];

for (const item of items) {
  const executions = item.json.executions || [];

  // Build numbered list of errors
  const numberedLines = [];
  for (let i = 0; i < executions.length; i++) {
    const e = executions[i];
    const execId = e.execution_id || "unknown";
    const failedNode = e.failed_node || "unknown";
    const errName = e.error_name || "unknown";
    const errMsg = (e.error_message || "no message").replace(/\s+/g, " ").trim();
    numberedLines.push(
      (i + 1) + ". Execution " + execId + ": " + errName + " at " + failedNode + ". Message: " + errMsg
    );
  }

  const systemLines = [
    "You are a workflow failure classifier. You will receive a numbered list of n8n execution errors. For each error, return exactly one classification from this fixed list:",
    "",
    "- transient_network: connection reset, DNS failure, timeout, ECONNREFUSED, ETIMEDOUT",
    "- transient_rate_limit: 429, rate limit exceeded, quota exceeded, too many requests",
    "- permanent_auth: 401, 403, invalid credentials, authentication failed",
    "- permanent_schema: column does not exist, null value violates constraint, invalid input syntax, JSON parse error",
    "- permanent_config: missing credential, node not configured, workflow not active, node not executed",
    "- unknown: none of the above",
    "",
    "Return JSON only, no markdown, no prose. The JSON must contain a single key 'classifications' whose value is an array with exactly one object per input error, in the same order as the input. Each object must have these exact keys: index (zero-based integer matching the input position), classification (one of the six values above), confidence (number between 0 and 1), reasoning (one short sentence)."
  ];
  const systemPrompt = systemLines.join("\n");

  const userLines = [
    "Classify each of the following " + executions.length + " errors. Return exactly " + executions.length + " classifications in the same order.",
    "",
    numberedLines.join("\n")
  ];
  const userPrompt = userLines.join("\n");

  const body = {
    model: "openai/gpt-oss-20b",
    temperature: 0,
    reasoning_effort: "low",
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt }
    ]
  };

  results.push({
    json: {
      body_string: JSON.stringify(body)
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  const errorObj = d.data?.resultData?.error || {};
  results.push({
    json: {
      execution_id: d.id,
      workflow_id: d.workflowId,
      status: d.status,
      error_message: errorObj.message || null,
      error_name: errorObj.name || null,
      failed_node: d.data?.resultData?.lastNodeExecuted || null
    }
  });
}

return results;

const groqItem = $input.first().json;
const executions = $('Aggregate Executions').first().json.executions || [];

// Parse the Groq content string
let classifications = [];
let parseError = null;
try {
  const content = groqItem.choices[0].message.content;
  const parsed = JSON.parse(content);
  classifications = Array.isArray(parsed.classifications) ? parsed.classifications : [];
} catch (e) {
  parseError = e.message;
}

const results = [];

for (let i = 0; i < executions.length; i++) {
  const exec = executions[i];
  const cls = classifications[i] || null;

  results.push({
    json: {
      execution_id: exec.execution_id || null,
      workflow_id: exec.workflow_id || null,
      status: exec.status || null,
      error_message: exec.error_message || null,
      error_name: exec.error_name || null,
      failed_node: exec.failed_node || null,
      classification: cls && cls.classification ? cls.classification : "unknown",
      classification_confidence: cls && typeof cls.confidence === "number" ? cls.confidence : null,
      classification_reasoning: cls && cls.reasoning ? cls.reasoning : (parseError || "no classification returned")
    }
  });
}

// If Groq returned more classifications than executions, emit the extras with null execution fields
if (classifications.length > executions.length) {
  for (let i = executions.length; i < classifications.length; i++) {
    const cls = classifications[i];
    results.push({
      json: {
        execution_id: null,
        workflow_id: null,
        status: null,
        error_message: null,
        error_name: null,
        failed_node: null,
        classification: cls.classification || "unknown",
        classification_confidence: typeof cls.confidence === "number" ? cls.confidence : null,
        classification_reasoning: cls.reasoning || "orphan classification with no matching execution"
      }
    });
  }
}

return results;
